        },
        {
            "url": "https://www.sec.gov/Archives/edgar/data/1805284/000095014225000696/eh250601250_ex9901.htm",
            "name": "Rocket Companies press release (8-K Ex. 99.1) announcing Redfin acquisition"
        }
    ]
}

